public class LoggingProxy : DispatchProxy
{
    public object? Target { get; set; }
    protected override object? Invoke(MethodInfo? method, object?[]? args)
    {
        Console.WriteLine(method!.Name);
        return method.Invoke(Target, args);
    }
}
var svc = DispatchProxy.Create<IService, LoggingProxy>();
((LoggingProxy)(object)svc).Target = new Service();

Lazy<Service> lazy = new Lazy<Service>(() => new Service());
// first access constructs the real subject exactly once (thread-safe by default)
var value = lazy.Value;

